// <auto-generated-by-handoff>
// Layer 1 — Uomd.Core: Lyria 3.5 BGM Crossfader, 16 Ogg Vorbis SFX Cues & Chirp 3 HD Japanese VO Director
// (1:1 C# port of apps/game/src/audio/Music.ts & Sfx.ts).

using System;
using System.Collections.Generic;
using UnityEngine;

namespace Uomd.Core
{
    public sealed class AudioDirector : MonoBehaviour
    {
        private AudioSource _bgmSourceA;
        private AudioSource _bgmSourceB;
        private AudioSource _sfxSource;
        private AudioSource _voiceSource;
        private bool _usingSourceA = true;

        public string CurrentBgmCueId { get; private set; } = "";
        public float MasterVolume { get; set; } = 0.85f;
        public float BgmVolume { get; set; } = 0.70f;
        public float SfxVolume { get; set; } = 0.85f;
        public float VoiceVolume { get; set; } = 1.00f;
        public bool Muted { get; set; }

        private void Awake()
        {
            _bgmSourceA = gameObject.AddComponent<AudioSource>();
            _bgmSourceA.loop = true;
            _bgmSourceA.playOnAwake = false;

            _bgmSourceB = gameObject.AddComponent<AudioSource>();
            _bgmSourceB.loop = true;
            _bgmSourceB.playOnAwake = false;

            _sfxSource = gameObject.AddComponent<AudioSource>();
            _sfxSource.loop = false;
            _sfxSource.playOnAwake = false;

            _voiceSource = gameObject.AddComponent<AudioSource>();
            _voiceSource.loop = false;
            _voiceSource.playOnAwake = false;
        }

        /// <summary>
        /// Resolves the canonical Lyria 3.5 BGM motif for any story scene ID or location ID.
        /// </summary>
        public static string ResolveStoryMusicCue(string sceneId, string locationId = "")
        {
            if (string.IsNullOrEmpty(sceneId) && string.IsNullOrEmpty(locationId)) return "bgm_main_theme";

            if (!string.IsNullOrEmpty(sceneId))
            {
                if (sceneId.StartsWith("prologue", StringComparison.OrdinalIgnoreCase) ||
                    sceneId.StartsWith("entry_past", StringComparison.OrdinalIgnoreCase))
                {
                    return "bgm_prologue_before_the_road";
                }

                if (sceneId.Equals("opening_sad_scene", StringComparison.OrdinalIgnoreCase) ||
                    sceneId.Equals("part1_emotional_confession", StringComparison.OrdinalIgnoreCase) ||
                    sceneId.Equals("tutorial_t3_after", StringComparison.OrdinalIgnoreCase) ||
                    sceneId.StartsWith("cs_fadyme", StringComparison.OrdinalIgnoreCase))
                {
                    return "bgm_fadyme_theme";
                }

                if (sceneId.StartsWith("cs_mahmut", StringComparison.OrdinalIgnoreCase))
                {
                    return "bgm_mahmut_theme";
                }

                if (sceneId.Equals("part1_clockless_reveal", StringComparison.OrdinalIgnoreCase))
                {
                    return "bgm_clockless";
                }

                if (sceneId.Equals("ch1_first_oath", StringComparison.OrdinalIgnoreCase) ||
                    sceneId.Contains("_camp", StringComparison.OrdinalIgnoreCase))
                {
                    return "bgm_camp_night";
                }

                if (sceneId.Contains("_road", StringComparison.OrdinalIgnoreCase))
                {
                    return "bgm_road";
                }

                if (sceneId.Equals("node_2_5_pre", StringComparison.OrdinalIgnoreCase))
                {
                    return "bgm_bell_widow";
                }

                if (sceneId.Contains("t1", StringComparison.OrdinalIgnoreCase) ||
                    sceneId.StartsWith("node_1_1", StringComparison.OrdinalIgnoreCase) ||
                    sceneId.StartsWith("node_1_2", StringComparison.OrdinalIgnoreCase))
                {
                    return "bgm_ch1_ash_forest_calm";
                }

                if (sceneId.Contains("t2", StringComparison.OrdinalIgnoreCase) ||
                    sceneId.StartsWith("node_1_3", StringComparison.OrdinalIgnoreCase) ||
                    sceneId.StartsWith("node_1_4", StringComparison.OrdinalIgnoreCase))
                {
                    return "bgm_ch1_ash_forest_uneasy";
                }

                if (sceneId.Contains("t3", StringComparison.OrdinalIgnoreCase) ||
                    sceneId.StartsWith("node_1_5", StringComparison.OrdinalIgnoreCase))
                {
                    return "bgm_ch1_ash_forest_chaotic";
                }

                if (sceneId.StartsWith("node_2_", StringComparison.OrdinalIgnoreCase) || sceneId.Contains("ch2", StringComparison.OrdinalIgnoreCase)) return "bgm_ch2_cathedral";
                if (sceneId.StartsWith("node_3_", StringComparison.OrdinalIgnoreCase) || sceneId.Contains("ch3", StringComparison.OrdinalIgnoreCase)) return "bgm_ch3_oakhaven";
                if (sceneId.StartsWith("node_4_", StringComparison.OrdinalIgnoreCase) || sceneId.Contains("ch4", StringComparison.OrdinalIgnoreCase)) return "bgm_ch4_undercity";
                if (sceneId.StartsWith("node_5_", StringComparison.OrdinalIgnoreCase) || sceneId.Contains("ch5", StringComparison.OrdinalIgnoreCase)) return "bgm_ch5_bridge";
                if (sceneId.StartsWith("node_6_", StringComparison.OrdinalIgnoreCase) || sceneId.Contains("ch6", StringComparison.OrdinalIgnoreCase)) return "bgm_ch6_estate";
                if (sceneId.StartsWith("node_7_", StringComparison.OrdinalIgnoreCase) || sceneId.Contains("ch7", StringComparison.OrdinalIgnoreCase)) return "bgm_ch7_altar";
            }

            if (!string.IsNullOrEmpty(locationId))
            {
                return locationId switch
                {
                    "forest_whispering_ash" => "bgm_ch1_ash_forest_calm",
                    "cathedral_saint_luthos" => "bgm_ch2_cathedral",
                    "village_oakhaven" => "bgm_ch3_oakhaven",
                    "undercity_subterranean" => "bgm_ch4_undercity",
                    "bridge_forsaken" => "bgm_ch5_bridge",
                    "forgotten_stone_crossing" => "bgm_ch5_bridge",
                    "estate_ashen_lord" => "bgm_ch6_estate",
                    "altar_first_eclipse" => "bgm_ch7_altar",
                    "shelter_courtyard_dusk" => "bgm_camp_night",
                    _ => "bgm_main_theme",
                };
            }

            return "bgm_main_theme";
        }

        /// <summary>
        /// Resolves the canonical Lyria 3.5 battle/boss BGM motif for any encounter ID or boss unit ID.
        /// </summary>
        public static string ResolveBattleMusicCue(string encounterId, bool isBoss, string bossUnitId = "")
        {
            if (!string.IsNullOrEmpty(bossUnitId))
            {
                return bossUnitId switch
                {
                    "boss_hollow_stag" => "bgm_boss_beast",
                    "boss_bell_widow" => "bgm_boss_bell_widow",
                    "boss_inquisitor_vance" => "bgm_boss_human",
                    "boss_drowned_archivist" => "bgm_boss_wraith",
                    "boss_warden_galen" => "bgm_boss_human",
                    "boss_ashen_regent" => "bgm_boss_wraith",
                    "boss_eclipse_construct" => "bgm_boss_eclipse_construct",
                    _ => "bgm_boss_beast",
                };
            }

            if (isBoss && !string.IsNullOrEmpty(encounterId))
            {
                if (encounterId.Contains("1_5", StringComparison.OrdinalIgnoreCase)) return "bgm_boss_beast";
                if (encounterId.Contains("2_5", StringComparison.OrdinalIgnoreCase)) return "bgm_boss_bell_widow";
                if (encounterId.Contains("3_5", StringComparison.OrdinalIgnoreCase) || encounterId.Contains("5_5", StringComparison.OrdinalIgnoreCase)) return "bgm_boss_human";
                if (encounterId.Contains("4_5", StringComparison.OrdinalIgnoreCase) || encounterId.Contains("6_5", StringComparison.OrdinalIgnoreCase)) return "bgm_boss_wraith";
                if (encounterId.Contains("7_5", StringComparison.OrdinalIgnoreCase)) return "bgm_boss_eclipse_construct";
                return "bgm_boss_beast";
            }

            return "bgm_battle_field";
        }

        /// <summary>
        /// Resolves the canonical combat/menu voice or creature vocal effect cue ID for any Hero, Boss, or Enemy unit.
        /// </summary>
        public static string ResolveUnitCombatVoiceCue(string unitId, string action)
        {
            if (string.IsNullOrEmpty(unitId) || string.IsNullOrEmpty(action)) return "";

            if (unitId.Equals("fadyme", StringComparison.OrdinalIgnoreCase) ||
                unitId.Equals("mahmut", StringComparison.OrdinalIgnoreCase))
            {
                return $"vo_{unitId.ToLowerInvariant()}_{action.ToLowerInvariant()}";
            }

            if (unitId.StartsWith("boss_", StringComparison.OrdinalIgnoreCase))
            {
                string bossAct = action.ToLowerInvariant() switch
                {
                    "basic" or "basic_attack" or "active" or "active_skill" or "ultimate" => "attack",
                    "phase_break" or "phase_ward" or "phase" => "phase",
                    "defeat" or "death" => "defeat",
                    _ => "intro",
                };
                return $"vo_{unitId.ToLowerInvariant()}_{bossAct}";
            }

            string archetype = unitId.ToLowerInvariant() switch
            {
                "ash_wolf" => "beast",
                "glass_viper" => "serpent",
                "bellbound_dead" or "hollow_pilgrim" or "hollow_cleric" or "inkbound_dead" or "orchard_ghoul" or "royal_hollow" => "hollow",
                "bridge_revenant" or "estate_wraith" => "wraith",
                "choir_knight" or "corrupted_crown_guard" or "crownless_knight" or "lost_vow_knight" or "noble_retainer" or "corrupted_mercenary" => "knight",
                "chain_cultist" or "red_vial_alchemist" or "red_vial_scout" or "eclipse_sentinel" => "cultist",
                _ => "",
            };

            if (!string.IsNullOrEmpty(archetype))
            {
                string enemyAct = action.ToLowerInvariant() switch
                {
                    "hit" or "damage" => "hit",
                    "defeat" or "death" => "defeat",
                    _ => "attack",
                };
                return $"vo_enemy_{archetype}_{enemyAct}";
            }

            return "";
        }

        /// <summary>Set by the router after the media catalog loads; without it cues stay silent.</summary>
        public UomdMediaLoader Media { get; set; }

        private const float DefaultFadeSeconds = 1.8f; // Music.play fade in the TypeScript client
        private float _fadeSeconds = DefaultFadeSeconds;
        private float _fadeElapsed;
        private AudioSource _fadingOut;
        private double _loopStartSeconds;
        private float _lastBgmTime;

        private AudioSource ActiveBgm => _usingSourceA ? _bgmSourceA : _bgmSourceB;

        /// <summary>
        /// Crossfades to a music cue from art_manifest.json "music". The track loops from its loop_start_s, as the
        /// TypeScript client did, so the intro plays once. Calling it again with the current cue does nothing.
        /// </summary>
        public void PlayBgmCue(string cueId, AudioClip clip = null)
        {
            if (string.IsNullOrEmpty(cueId) || cueId == CurrentBgmCueId) return;
            CurrentBgmCueId = cueId;
            if (clip != null)
            {
                StartBgm(clip, 0.0);
                return;
            }
            if (Media != null && Media.Catalog.TryGetMusic(cueId, out var track)) _ = LoadAndPlayBgm(cueId, track);
            else Debug.LogWarning($"[AudioDirector] no music for cue '{cueId}'");
        }

        public void StopBgm(float fadeSeconds = DefaultFadeSeconds)
        {
            CurrentBgmCueId = "";
            _fadeSeconds = Mathf.Max(0.01f, fadeSeconds);
            _fadeElapsed = 0f;
            _fadingOut = ActiveBgm;
        }

        public void PlaySfx(string sfxId, AudioClip clip = null)
        {
            if (Muted || string.IsNullOrEmpty(sfxId)) return;
            if (clip != null)
            {
                _sfxSource.PlayOneShot(clip, MasterVolume * SfxVolume);
                return;
            }
            if (Media != null && Media.Catalog.TryGetSound(sfxId, out var cue)) _ = LoadAndPlaySfx(cue);
        }

        /// <summary>Plays a voice line from presentation.json "voices"; the previous line stops.</summary>
        public void PlayVoiceLine(string lineId, AudioClip clip = null)
        {
            _voiceSource.Stop();
            _pendingVoiceLine = lineId;
            if (Muted || string.IsNullOrEmpty(lineId)) return;
            if (clip != null)
            {
                StartVoice(clip);
                return;
            }
            if (Media != null && Media.Catalog.TryGetVoice(lineId, out var cue)) _ = LoadAndPlayVoice(lineId, cue);
        }

        public void StopVoiceLine()
        {
            _pendingVoiceLine = null;
            if (_voiceSource != null) _voiceSource.Stop();
        }

        public bool VoicePlaying => _voiceSource != null && _voiceSource.isPlaying;

        /// <summary>Freezes music and voice in place (prologue PAUSE); SetPaused(false) continues from the same point.</summary>
        public void SetPaused(bool paused)
        {
            foreach (var source in new[] { _bgmSourceA, _bgmSourceB, _voiceSource })
            {
                if (source == null) continue;
                if (paused) source.Pause();
                else source.UnPause();
            }
        }

        private string _pendingVoiceLine;

        private async Awaitable LoadAndPlayBgm(string cueId, MusicTrack track)
        {
            var clip = await Media.ClipAsync(track.File, streamLong: true);
            if (clip == null || CurrentBgmCueId != cueId) return; // another cue was requested while loading
            StartBgm(clip, track.LoopStartSeconds);
        }

        private async Awaitable LoadAndPlaySfx(SoundCue cue)
        {
            var clip = await Media.ClipAsync(cue.File);
            if (clip != null && !Muted) _sfxSource.PlayOneShot(clip, MasterVolume * SfxVolume * cue.Volume);
        }

        private async Awaitable LoadAndPlayVoice(string lineId, SoundCue cue)
        {
            var clip = await Media.ClipAsync(cue.File);
            if (clip != null && _pendingVoiceLine == lineId && !Muted) StartVoice(clip);
        }

        private void StartBgm(AudioClip clip, double loopStartSeconds)
        {
            _fadingOut = ActiveBgm.isPlaying ? ActiveBgm : null;
            _usingSourceA = !_usingSourceA;
            var next = ActiveBgm;
            next.clip = clip;
            next.loop = true;
            next.volume = 0f;
            next.time = 0f;
            next.mute = Muted;
            next.Play();
            _loopStartSeconds = loopStartSeconds > 0 && loopStartSeconds < clip.length ? loopStartSeconds : 0.0;
            _lastBgmTime = 0f;
            _fadeSeconds = DefaultFadeSeconds;
            _fadeElapsed = 0f;
        }

        private void StartVoice(AudioClip clip)
        {
            _voiceSource.clip = clip;
            _voiceSource.volume = MasterVolume * VoiceVolume;
            _voiceSource.Play();
        }

        private void Update()
        {
            float target = MasterVolume * BgmVolume;
            var active = ActiveBgm;
            if (_fadeElapsed < _fadeSeconds)
            {
                _fadeElapsed += Time.unscaledDeltaTime;
                float k = Mathf.Clamp01(_fadeElapsed / _fadeSeconds);
                if (!string.IsNullOrEmpty(CurrentBgmCueId)) active.volume = target * k;
                if (_fadingOut != null)
                {
                    _fadingOut.volume = Mathf.Min(_fadingOut.volume, target * (1f - k));
                    if (k >= 1f)
                    {
                        _fadingOut.Stop();
                        _fadingOut = null;
                    }
                }
            }
            else if (!string.IsNullOrEmpty(CurrentBgmCueId))
            {
                active.volume = target;
            }

            // AudioSource loops to 0; jump to the track's loop point instead so the intro is heard once.
            if (active.isPlaying && _loopStartSeconds > 0)
            {
                if (active.time + 0.5f < _lastBgmTime) active.time = (float)_loopStartSeconds;
                _lastBgmTime = active.time;
            }
            _bgmSourceA.mute = _bgmSourceB.mute = _voiceSource.mute = Muted;
        }
    }
}
